#include <cstddef>
#include <cstdint>
#include <climits>
namespace{constexpr std::size_t D=8,L=26;void put64(std::uint8_t*o,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t j=0;j<8;j++){o[j]=static_cast<std::uint8_t>(b&255U);b>>=8;}}}
extern "C" std::int64_t concave_gap_alignment_global(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap)noexcept{if(!in||len<5||len>L)return -1;auto nr=in[0],mr=in[1];if(nr<1||nr>D||mr<1||mr>D)return -1;auto n=static_cast<std::size_t>(nr),m=static_cast<std::size_t>(mr),g=n>m?n:m;if(len!=2+n+m+g)return -1;std::int64_t x[D]{},y[D]{},w[D]{};std::size_t p=2;for(std::size_t i=0;i<n;i++){x[i]=in[p++];if(x[i]<0||x[i]>3)return -1;}for(std::size_t j=0;j<m;j++){y[j]=in[p++];if(y[j]<0||y[j]>3)return -1;}std::int64_t slope=LLONG_MAX;for(std::size_t k=0;k<g;k++){w[k]=in[p++];if(w[k]<0||w[k]>100)return -1;auto d=w[k]-(k?w[k-1]:0);if(k&&w[k]<w[k-1])return -1;if(k&&d>slope)return -1;slope=d;}if(!out||cap<8)return -2;std::int64_t dp[D+1][D+1];for(auto&i:dp)for(auto&v:i)v=LLONG_MAX/4;dp[0][0]=0;for(std::size_t i=0;i<=n;i++)for(std::size_t j=0;j<=m;j++){if(!i&&!j)continue;auto best=LLONG_MAX/4;if(i&&j){auto z=dp[i-1][j-1]+(x[i-1]!=y[j-1]);if(z<best)best=z;}for(std::size_t z=1;z<=i;z++){auto c=dp[i-z][j]+w[z-1];if(c<best)best=c;}for(std::size_t z=1;z<=j;z++){auto c=dp[i][j-z]+w[z-1];if(c<best)best=c;}dp[i][j]=best;}put64(out,dp[n][m]);return 8;}
